vec2 fstep2(vec2 xy)
{
//Eo.S. replaced 1.0/res with resInv so shader doesn't have to do division
return resInv*round(res*xy);
}
float GetDist(vec2 uvi)
{
vec2 tmp;
tmp = fstep2( texture(sampler_pw_main, uvi).gb );
//return pow( 1.0-( res2Inv*(tmp.x-0.505) + tmp.y ), q3 );//Eo.S> replaced 1.0 / q30 with q3
return 1.0-( res2Inv*(tmp.x-0.505) + tmp.y );//Eo.S> q3 is always 1, so remove pow()
}
vec2 PutDist(float x) {
float tmp; x = pow(x,q30);
tmp = fstep2(1.0 - x);
return (vec2(res2*((1.0 - x)-tmp)+.495,tmp));
}
float MinDist (vec2 uvi)
{
float tmp; vec4 nb; vec4 nb2; vec2 pix;
pix = (vec2(1.0)/uTexSize)*(1.0+length(uvi-0.5)*3.0);
tmp = GetDist(uvi);
nb.x = GetDist(uvi+pix*vec2(-1,-1));
nb.y = GetDist(uvi+pix*vec2( 1.0 ,-1));
nb.z = GetDist(uvi+pix*vec2( 1.0 , 1.0 ));
nb.w = GetDist(uvi+pix*vec2(-1, 1.0 ));
//tmp = min(tmp,min(min(min(nb.x, nb.y),nb.z),nb.w)) ;
nb2.x = GetDist(uvi+pix*vec2( 0.0 ,-1));
nb2.y = GetDist(uvi+pix*vec2( 1.0 , 0.0 ));
nb2.z = GetDist(uvi+pix*vec2( 0.0 , 1.0 ));
nb2.w = GetDist(uvi+pix*vec2(-1, 0.0 ));
//tmp = min(tmp,min(min(min(nb.x, nb.y),nb.z),nb.w)) ;
//Eo.S. more efficient usage of min to get min value of all 8 GetDist() calls, removes 11ALU
nb = min( nb, nb2 );
nb.xy = min( nb.xy, nb.zw );
tmp = min( nb.x, nb.y );
return tmp;
}
vec3 Get1 (vec2 uvi)
{
vec3 tmp; vec2 pix;
tmp = GetBlur1(uvi) * 3.0;
return mix(GetPixel(uvi),tmp / 3.0,change * 4.0);
}
vec3 mbox (vec3 uvi)
{
vec3 zz, zz0; float tmp, li;
zz = uvi; zz0 = zz;
for (int n = 0; n <= 7; n++)
{
zz = 2.0*clamp(zz,-1, 1.0 )-zz;  tmp = dot(zz,zz);
if (tmp <= 0.25) {zz *= 4;} else if (tmp <= 1) {zz /= pow(tmp, 1.0 );}
zz = 2.6*zz + zz0;
}
return zz;
}
dist = min(dist,GetDist(uv));
vec3 uv2 = multiply(vec3(uv1*dist,dist-.02)/myzoom,RotMat)+CamPos;
uv2 = (fract(uv2/8.0+.5)-.5)*8.0;
box = mbox (uv2);
