struc = length(box.zy) /limit;
if ((dist <= GetDist(uv)) && (len < limit) && (dist > 0.005))
{
ret.r = (1.0 - sustain)*struc+sustain*(Get1(uv).r); ret.gb=  PutDist(dist);
}
else
{
ret = texture(sampler_pc_main,uv_orig) * vec3(sustain, 1.0, 1.0)-vec3(0.0, 0.0, change);
}
//ret = noise;
}

