vec3 noise = fract(8.0 * texture(sampler_noise_lq,uv+rand_frame.yz));
dist = noise.r;
if (noise.g > 0.2)
{
//dist = MinDist( (noise.zy-0.5) * 0.003 +uv ) +  0.005 * (noise.x-0.4) * abs(noise.y-0.5);
vec3 noiseBiased = noise - vec3( 0.4, 0.5, 0.5 );//Eo.S. combine the subtraction on noise to a single vec3 to ensure compiler does the subtraction in a single ALU
dist = MinDist( (noiseBiased.zy) * 0.003 +uv ) +  0.005 * (noiseBiased.x) * abs(noiseBiased.y);
  fragColor = vec4(ret, 1.0);
}

